CREATE TABLE "public".${tableName} (
    "id" int8 NOT NULL,
    "code" varchar(50) COLLATE "pg_catalog"."default",
    "record_time" timestamp(6),
    "value" numeric(14,4),
    "create_time" timestamp(6) NOT NULL,
    CONSTRAINT ${idIndex} PRIMARY KEY ("id")
);
ALTER TABLE "public".${tableName}
    OWNER TO "gpadmin";

CREATE INDEX ${indexA} ON "public".${tableName}  USING btree (
    "code" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST,
    "record_time" "pg_catalog"."timestamp_ops" DESC NULLS LAST
    );

CREATE INDEX ${indexB} ON "public".${tableName}  USING btree (
    "record_time" "pg_catalog"."timestamp_ops" DESC NULLS LAST,
    "code" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
    );
